titles = {}
for pl, (title, found, defect, siblings, cannot, criteria, already) in BUGS.items():
    body = [f"Found by the M6 T14 state-tests audit (#661), {pl} ({found}) (`{FOLDER}`, on `feature/m6-tooling-state-tests-661`). A test that fails at the hash, or passes without proving, is a defect (D-WORKFLOW-187); a lane will act on it.", "",
            "## Code trace", "", f"**How it was found:** `04-analysis.md` {found}.", "", "**The defect, at its source (`8ebaf8daad` unless named):**"]
    body += [f"- {d}" for d in defect]
    body += ["", f"**Every sibling hunted:** {siblings}", "", f"**What reading cannot prove:** {cannot}", "", VM, "", "## Acceptance criteria", ""]
    body += [f"- [ ] {c}" for c in criteria]
    body += ["", f"**Already written:** {already}", "", "Refs #661"]
    open(os.path.join(out, f"{pl}.md"), "w").write("\n".join(body) + "\n")
    titles[pl] = "Bug: " + title
json.dump(titles, open(os.path.join(out, "titles.json"), "w"), indent=2)
print(len(titles), "bodies")
